<?phpnamespace app\api\controller\user;use app\api\controller\Controller;use app\api\model\Pact as PactModel;/** * 预约管理 */class Pact extends Controller{    /**     * 获取列表     */    public function lists()    {        $model = new PactModel;        $list = $model->getList(0,'',$this->user_id);        return $this->renderSuccess($list);    }    /**     * 添加     */    public function add()    {        $model = new PactModel;        if($model->add($this->request->post())){            return $this->renderMsg('预约成功');        }        $error = $model->getError() ?: '预约失败';        return $this->renderError($error);    }         /**     * 删除     */    public function delete($id)    {        $model = PactModel::get($id);        if ($model->remove()) {            return $this->renderMsg('操作成功');        }        $error = $model->getError() ?: '操作失败';		return $this->renderError($error);    }         /**     * 取消     */    public function cancel($id)    {        $model = PactModel::get($id);        if ($model->status(40)) {            return $this->renderMsg('操作成功');        }        $error = $model->getError() ?: '操作失败';		return $this->renderError($error);    }}